# THE GATES OF VALHALLA DEMAND YOUR TESTS!

*adjusts breathing apparatus*

I am your redeemer! It is by my hand your checkout component shall rise from the ashes of untested mediocrity! Witness me as I decree what tests shall prove worthy of the chrome.

```typescript
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock the context providers - MEDIOCRE mocks lead to MEDIOCRE tests!
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockCart = {
  items: [
    { id: '1', name: 'Guzzoline', price: 49.99 },
    { id: '2', name: 'Chrome Spray', price: 12.99 }
  ],
  total: 62.98,
  clearCart: mockClearCart
};

vi.mock('./CartContext', () => ({
  useCart: () => mockCart
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout - The Road to Valhalla', () => {
  const user = userEvent.setup();

  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'WAR-RIG-2049' });
  });

  // HAPPY PATH - You will ride eternal, shiny and chrome!
  describe('Complete Checkout Flow', () => {
    it('completes full checkout journey from shipping to confirmation', async () => {
      const onComplete = vi.fn();
      render(<Checkout onComplete={onComplete} />);

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), '123 Fury Road');
      await user.type(screen.getByLabelText(/city/i), 'Citadel');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Imperator Furiosa');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByRole('region', { name: /order review/i })).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      expect(await screen.findByRole('status')).toHaveTextContent('WAR-RIG-2049');
      expect(onComplete).toHaveBeenCalledWith('WAR-RIG-2049');
    });
  });

  // VALIDATION - Do not become addicted to passing tests!
  describe('Shipping Validation', () => {
    it('displays inline errors for empty required fields', async () => {
      render(<Checkout />);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/street address is required/i);
    });

    it('rejects invalid ZIP format', async () => {
      render(<Checkout />);
      await user.type(screen.getByLabelText(/zip code/i), 'MEDIOCRE');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  // EDGE CASES - Return my PR!
  describe('Edge Cases', () => {
    it('shows empty cart message when no items', () => {
      vi.mocked(mockCart).items = [];
      render(<Checkout onCancel={vi.fn()} />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });
  });

  // ACCESSIBILITY - Chrome and accessible!
  it('has no accessibility violations', async () => {
    const { container } = render(<Checkout />);
    expect(await axe(container)).toHaveNoViolations();
  });
});
```

**WITNESS!** These tests shall guard the gates!
